import json, re, html
from pathlib import Path
from collections import defaultdict

wt5 = Path('/Users/sinchunyeung/.treehouse/paper2notes-652c2c/5/paper2notes/notes/book5')
paper_stems = defaultdict(set)
for p in wt5.rglob('*.html'):
    text = p.read_text()
    for m in re.finditer(r'<li>(.*?)</li>', text, re.S):
        block = m.group(1)
        stem_m = re.search(r'<p>(.*?)</p>', block, re.S)
        if not stem_m:
            continue
        stem = re.sub(r'<[^>]+>', '', stem_m.group(1))
        stem = html.unescape(re.sub(r'\s+', ' ', stem)).strip()
        stem = re.sub(r'\s*extension\s*$', '', stem, flags=re.I).strip()
        # drop latex so KaTeX-rendered text still matches
        stem = re.split(r'\\\(', stem, 1)[0].strip()
        for href in re.findall(r'href="[^"]*#(dse-[a-z0-9-]+)"', block):
